import RNA
target="((..(((..((((..((....((..((((....))....))..))))..))....))..))((..((..((..((((..((....((..((((..((....((....))))..))....))..))))..))((..((..((....))((..((((..((....((..((((....))....))..))))..))....))..))))..))..))..))((..((....((..((((..((....((....))))..))....))..))))..))))..))..)..))"
n=len(target)
stack=[];pairs=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop();pairs.append((j,i))

# Build parent/child relationship to find stem depth
pairmap={}
for i,j in pairs:
    pairmap[i]=j; pairmap[j]=i
# find innermost
children={}
for i,j in pairs:
    children[(i,j)]=[]
for i,j in pairs:
    # find smallest enclosing pair
    best=None
    for k in range(i):
        if k in pairmap and pairmap[k]>j:
            if best is None or pairmap[k]<pairmap[best]:
                best=k
    if best is not None:
        children[(best,pairmap[best])].append((i,j))

# depth: 0 = innermost
depth={}
def setdepth(p,d):
    depth[p]=d
    for c in children[p]:
        setdepth(c,d+1)
roots=[p for p in pairs if p not in depth]
for r in roots:
    setdepth(r,0)
for p in pairs:
    if p not in depth:
        depth[p]=0

caps={(28,33),(102,107),(140,145),(170,175),(244,249)}
seq=['U']*n
# caps GAAA on C-G
for (i,j) in caps:
    seq[i]='C'; seq[j]='G'
    seq[i+1]='G'; seq[i+2]='A'; seq[i+3]='A'; seq[i+4]='A'
# assign pairs: depth 1 (first stem out) -> G-C; deeper -> alternating
for (i,j) in pairs:
    if (i,j) in caps: continue
    d=depth[(i,j)]
    if d==1:
        seq[i]='G'; seq[j]='C'  # strong, stacks on cap
    elif d==2:
        seq[i]='G'; seq[j]='C'
    else:
        seq[i]='A'; seq[j]='U'  # weak outer
s=''.join(seq)
fc=RNA.fold_compound(s); ss,mfe=fc.mfe()
print("match",ss==target,"mfe",mfe,"diff",sum(1 for k in range(n) if ss[k]!=target[k]))
print("ss ",ss[:80])
print("tgt",target[:80])
EOF
